'use strict';
const LayoutUI=(()=>{
  const L=FoldLayout,el=id=>document.getElementById(id);let api,selected=null,before=null;
  const state=()=>api.state(),layout=()=>L.normalize(state().layout),active=()=>Boolean(api&&state().layout?.enabled);
  function update(value,commit=true,extra={}){api.change({...state(),...extra,layout:value},commit)}
  function toggle(){const p=state(),l=layout();if(l.enabled){update({...l,enabled:false});return}const extra=p.paper==='auto'?{paper:'a4',paperW:210,paperH:297}:{};const sheet={...p,...extra};if(!l.items.length)l.items=[L.first(api.geometry(),sheet)];selected=l.items[0].id;api.flat();api.disableArtwork();update({...l,enabled:true},true,extra);el('sheetLayoutPanel').open=true;api.center()}
  function sync(){if(!api||!api.geometry())return;const l=layout(),p=state();if(!l.items.some(i=>i.id===selected))selected=l.items[0]?.id||null;const enabled=l.enabled;el('layoutTool').textContent=enabled?'Design':'Arrange';el('layoutTool').setAttribute('aria-pressed',String(enabled));el('sheetLayoutPanel').hidden=!enabled;el('artTool').disabled=enabled;el('fitA4').disabled=enabled;el('editHandles').disabled=enabled;el('layoutActions').hidden=!enabled;el('layoutCount').textContent=`${l.items.length} ${l.items.length===1?'copy':'copies'}`;
    if(!enabled)return;const check=L.check(l,api.geometry(),p),item=l.items.find(i=>i.id===selected);el('layoutMessage').textContent=check.fits?`${l.items.length} copies fit this sheet at actual size.`:`${check.outside.length} outside margins · ${check.pairs.length} overlapping / too-close pairs`;el('layoutMessage').classList.toggle('layout-warning',!check.fits);el('layoutCopy').innerHTML=l.items.map((i,n)=>`<option value="${i.id}">Copy ${n+1} · ${i.rotation}°</option>`).join('');el('layoutCopy').value=selected;
    for(const [key,value]of [['layoutX',item?.x],['layoutY',item?.y],['layoutAngle',item?.rotation],['layoutGap',l.gap]])if(document.activeElement!==el(key))el(key).value=key==='layoutAngle'?value:api.display(value||0);el('layoutRotateAuto').checked=l.autoRotate;document.querySelectorAll('.layout-unit').forEach(node=>node.textContent=api.unit());el('layoutDelete').disabled=l.items.length<=1;el('layoutDuplicate').disabled=l.items.length>=200;
  }
  function select(id){selected=id;sync();api.refresh()}
  function add(){const l=layout(),copy=L.duplicate(l,api.geometry(),state(),selected);if(!copy){api.toast(l.items.length>=200?'Maximum 200 copies per sheet.':'No free space for another copy. Reduce dimensions or use a larger sheet.');return}selected=copy.id;update({...l,items:[...l.items,copy]});api.toast('Copy added at actual size.')}
  function rotate(angle){const l=layout(),g=api.geometry(),p=state();update({...l,items:l.items.map(i=>i.id===selected?L.rotate(i,g,p,angle==null?i.rotation+90:angle):i)})}
  function remove(){const l=layout();if(l.items.length<=1)return;update({...l,items:l.items.filter(i=>i.id!==selected)});sync()}
  function fill(){const l=layout(),items=L.pack(api.geometry(),state(),l.gap,l.autoRotate);if(!items.length){api.toast('The current dieline does not fit the printable area. Reduce its dimensions first.');return}selected=items[0].id;update({...l,items});api.center();api.toast(`Placed ${items.length} copies at actual size${items.length===200?' (200-copy limit)':''}.`)}
  function drag(start,id,dx,dy,snap=1){const l=L.normalize(start.layout),g=api.geometry();api.change({...start,layout:{...l,items:l.items.map(i=>i.id===id?L.move(i,g,start,dx,dy,snap):i)}},false)}
  function bounds(g,p,fit){if(!active())return null;const rects=layout().items.map(i=>L.rect(i,g)),x=Math.min(0,...rects.map(r=>r.x)),y=Math.min(0,...rects.map(r=>r.y));return{x,y,w:Math.max(fit.sheetW,...rects.map(r=>r.x+r.w))-x,h:Math.max(fit.sheetH,...rects.map(r=>r.y+r.h))-y}}
  function markup(g,p,u,paths){const l=layout(),bad=new Set(L.check(l,g,p).bad);return `<g id="dielineScene"><defs><g id="layout-master">${paths(g)}</g></defs>${l.items.map((i,n)=>{const r=L.rect(i,g);return `<g data-sheet-copy="${i.id}"><g transform="${L.transform(i,g)}"><use href="#layout-master"/></g><rect data-layout-id="${i.id}" class="layout-copy ${i.id===selected?'copy-selected':''} ${bad.has(i.id)?'copy-invalid':''}" role="button" tabindex="0" aria-label="Select copy ${n+1}, ${i.rotation} degrees" x="${r.x}" y="${r.y}" width="${r.w}" height="${r.h}" stroke-width="${u*1.2}" stroke-dasharray="${4*u} ${3*u}"><title>Copy ${n+1} · ${i.rotation}° · drag to position</title></rect>${i.id===selected?`<text x="${r.x}" y="${r.y-4*u}" font-size="${10*u}" fill="#647c4d" pointer-events="none">${n+1} · ${i.rotation}°</text>`:''}</g>`}).join('')}</g>`}
  function init(config){api=config;document.querySelector('.canvas-tools').insertAdjacentHTML('beforeend',`<div class="sheet-layout-tools"><button id="layoutTool" aria-pressed="false">Sheet layout</button><div id="layoutActions" hidden><span id="layoutCount">1 copy</span><button id="layoutDuplicate" title="Duplicate selected copy (Ctrl+D)">Duplicate</button><button id="layoutRotate" title="Rotate selected copy 90 degrees (R)">Rotate 90°</button><button id="layoutDelete" title="Remove selected copy (Delete)">Remove</button><button id="layoutFill">Fill sheet</button></div></div>`);
    el('artworkPanel').insertAdjacentHTML('beforebegin',`<details id="sheetLayoutPanel" open hidden><summary>Copies on sheet</summary><p id="layoutMessage" role="status"></p><label class="field">Selected copy<select id="layoutCopy" aria-label="Selected sheet copy"></select></label><div class="field-grid"><label class="field">X from sheet edge<div><input id="layoutX" type="number" step="any" aria-label="Copy X position"><span class="layout-unit">mm</span></div></label><label class="field">Y from sheet edge<div><input id="layoutY" type="number" step="any" aria-label="Copy Y position"><span class="layout-unit">mm</span></div></label><label class="field">Rotation<div><input id="layoutAngle" type="number" step="1" min="-36000" max="36000" aria-label="Copy rotation"><span>°</span></div></label><label class="field">Copy gap<div><input id="layoutGap" type="number" min="0" step="any" aria-label="Gap between copies"><span class="layout-unit">mm</span></div></label></div><label class="layout-checkbox"><input type="checkbox" id="layoutRotateAuto" checked> Allow 90° rotation when filling</label><p class="field-hint">Drag copies on the sheet. R rotates; Ctrl+D duplicates; Delete removes. Arrow keys nudge; Shift = 10 mm. Red outlines mean overlap or overflow.</p><p class="field-hint">Copies share the same dimensions, colors, and images. Fill sheet uses a grid and keeps actual dimensions. Maximum 200 copies.</p><button id="layoutOne">Reset to one copy</button></details>`);
    el('layoutTool').onclick=toggle;el('layoutDuplicate').onclick=add;el('layoutRotate').onclick=()=>rotate();el('layoutDelete').onclick=remove;el('layoutFill').onclick=fill;el('layoutCopy').onchange=e=>select(e.target.value);
    for(const id of ['layoutX','layoutY','layoutAngle','layoutGap']){const input=el(id);input.onfocus=()=>before=state();input.onchange=()=>{const raw=Number(input.value),value=id==='layoutAngle'?raw:api.from(raw);if(input.value===''||!Number.isFinite(value)||Math.abs(value)>50000||(id==='layoutGap'&&(value<0||value>50))){sync();return}const l=layout();if(id==='layoutGap')l.gap=value;else if(id==='layoutAngle')l.items=l.items.map(i=>i.id===selected?L.rotate(i,api.geometry(),state(),value):i);else l.items=l.items.map(i=>i.id===selected?{...i,[id==='layoutX'?'x':'y']:value}:i);update(l,false);api.commit(before||state());before=null;sync()};input.addEventListener('wheel',e=>e.preventDefault(),{passive:false})}
    el('layoutRotateAuto').onchange=e=>update({...layout(),autoRotate:e.target.checked});el('layoutOne').onclick=()=>{const l=layout();selected='copy-1';update({...l,items:[L.first(api.geometry(),state())]})};
    document.addEventListener('keydown',event=>{if(!active()||event.defaultPrevented||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='d'){event.preventDefault();add()}else if(event.key.toLowerCase()==='r'&&!event.ctrlKey&&!event.metaKey){event.preventDefault();rotate()}else if(['Delete','Backspace'].includes(event.key)){event.preventDefault();remove()}});
  }
  return{init,sync,active,select,drag,bounds,markup,rotate,remove,add};
})();
